print("Demo 1 input grid (visual):")
for i, row in enumerate(d1_in):
    print(f"Row {i}: {' '.join(f'{v:2d}' for v in row)}")
    for j, val in enumerate(row):
        if val == 5:
            print(f"   Found 5 at ({i},{j})")

# Let me carefully compare what my computed function produces vs expected
d1_exp_independent = [
    row[:] for row in d1_out  # Make a deep copy
]

# Run transform on Demo 1 input
h, w = len(d1_in), len(d1_in[0])
output = [row[:] for row in d1_in]  # Start with original

# Find isolated 5s
fives = [(r, c) for r in range(h) for c in range(w) if d1_in[r][c] == 5]
isolated_fives = []
for r, c in fives:
    hasNeighbor = any(d1_in[r+dr][c+dc] != 0 
                     for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] 
                     if 0 <= r+dr < h and 0 <= c+dc < w)
    if not hasNeighbor:
        isolated_fives.append((r, c))

# Find pattern
nonisos = [(r, c) for r in range(h) for c in range(w) 
           if d1_in[r][c] != 0 and (r, c) not in isolated_fives]
min_r, min_c = min(r for r,c in nonisos), min(c for r,c in nonisos)
max_r, max_c = max(r for r,c in nonisos), max(c for r,c in nonisos)
h_pat = max_r - min_r + 1
w_pat = max_c - min_c + 1
pattern = [[d1_in[r][c] for c in range(min_c, max_c + 1)] for r in range(min_r, max_r + 1)]

# Find 5 position in pattern
five_pos = None
for pr in range(h_pat):
    for pc in range(w_pat):
        if pattern[pr][pc] == 5:
            five_pos = (pr, pc)
            break

if five_pos:
    for iso_r, iso_c in isolated_fives:
        copy_pattern = [[v if v != 5 else 0 for v in row] for row in pattern]
        new_start_r, new_start_c = iso_r - five_pos[0], iso_c - five_pos[1]

        print(f"Copied pattern with 5->0, placed at ({new_start_r}, {new_start_c})")
        for pr, row in enumerate(copy_pattern):
            for pc, val in enumerate(row):
                out_r, out_c = new_start_r + pr, new_start_c + pc
                if 0 <= out_r < h and 0 <= out_c < w:
                    print(f"  copying ({out_r},{out_c}) = {val}")

    output_should_be = [row[:] for row in d1_in]  # Reset
    for iso_r, iso_c in isolated_fives:
        copy_pattern = [[v if v != 5 else 0 for v in row] for row in pattern]
        new_start_r, new_start_c = iso_r - five_pos[0], iso_c - five_pos[1]

        for pr, row in enumerate(copy_pattern):
            for pc, val in enumerate(row):
                out_r, out_c = new_start_r + pr, new_start_c + pc
                if 0 <= out_r < h and 0 <= out_c < w:
                    output_should_be[out_r][out_c] = val

    print("\n=== Computed output ===")
    for row in output_should_be:
        print(row)

    print("\n=== Expected output ===")
    for row in d1_out:
        print(row)

    print("\n=== Difference (non-zero cells where they differ) ===")
    for r in range(h):
        for c in range(w):
            if d1_exp_independent[r][c] != output_should_be[r][c]:
                print(f"  ({r},{c}): computed={output_should_be[r][c]}, expected={d1_exp_independent[r][c]}")

